NIGHT_LOADED({"seed":1103,"generated_at":"2026-10-21T06:00:00Z","chain":[1,4,2,3,5],"frame":{"collector":"J.D.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.D.","note_final":"Goed opgeborgen. Morgen om negen. — J.D.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.D.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.D.","initials":"J.D.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.D.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":9,"drawers":[{"id":"1-1","type":"P4","difficulty":1.5216,"rank":0.092,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"KOOIJMAN1128","role":"top","render":{"description":"Kees Stolwijk vertelt dat de vader van zijn vrouw vroeger in Honkoop woonde. Toen ze ergens liepen, zei haar vader ineens","place":"Hoenkoop","prov":"Utr.","year":1963,"code":"SINSAG 0481","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/72618","half":"top"},"home":"1-1"},{"id":"c2","story_id":"CJ009012","role":"distractor","render":{"description":"Hij wordt tot drie keer toe van de weg afgezet. Tenslotte wordt hij in een sloot gegooid. Dat heeft een lijkstatie gedaaan, die hij in de weg liep.","half":"bottom","code":"SINSAG 0481"},"home":"1-1"},{"id":"c3","story_id":"CJ056404","role":"distractor","render":{"description":"Een week later zat de oude vrouw buiten en zag ze weer een zwart lint. Weer een week later stierf ze. Het zwarte lint was de lijkstoet. Die had ze vantevoren gezien.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c4","story_id":"CJ120301","role":"distractor","render":{"description":"Het is een voorbode van de dood van zijn vrouw.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c5","story_id":"CJ025002","role":"distractor","render":{"description":"Maar er was niets en niemand te zien. Een paar dagen later werden er aardappels gestolen. Toen was precies hetzelfde geritsel te horen als eerder.","half":"bottom","code":"SINSAG 0487"},"home":"1-1"},{"id":"c6","story_id":"CJ086402","role":"distractor","render":{"description":"Hij vergat ook elke keer iets, waardoor hij al weer drie keer thuis was geweest. Diezelfde week is hij bij het zwemmen verdronken.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c7","story_id":"CBAK0030","role":"distractor","render":{"description":"Ze ziet wel een schim in de gedaante van een duif vliegen. Dat moet een voorteken van de dood van haar broer een paar dagen later zijn geweest.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c8","story_id":"GENDT140","role":"distractor","render":{"description":"Een paar dagen later sterft de vader en komen de buren bidden voor de overledene.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c9","story_id":"WEV015702","role":"distractor","render":{"description":"Korte tijd later sterft pasgeboren kind, buren dragen het kistje, en blaft een hond.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c10","story_id":"KOOIJMAN1128","role":"bottom","render":{"description":"dat iemand op zij moest gaan. Dat wilden ze niet. Hij zag wel wat eraan kwam en de andere niet. Mevrouw Stolwijk vertelt dat haar vader riep dat ze op zij moesten gaan. Er kwam namelijk een begrafenisstoet aan.","half":"bottom","code":"SINSAG 0481"},"home":"1-1"},{"id":"c11","story_id":"CJ011207","role":"distractor","render":{"description":"Het buurmeisje zegt: \"De eerste die uit de deur komt, die zal het wezen, zegt men.\" De vrouw zegt dat ze hoopt dat zij het niet zal zijn. Even later gaat het buurmeisje naar haar zus. De man van haar zus is zijn werkbroek vergeten, en het meisje brengt hem die achterna. Ze had hem al aangehouden, toen ze struikelde en rechtuit op de straat viel. Ze was op slag dood.","half":"bottom","code":"SINSAG 0486"},"home":"1-1"},{"id":"c12","story_id":"CJ123403","role":"distractor","render":{"description":"Sommige mensen krijgen ook voorgezichten van een brand. Anderen horen op een bepaalde plaats al timmergeluiden hoewel er veel later pas een huis gebouwd wordt.","half":"bottom","code":"SINSAG 0489"},"home":"1-1"},{"id":"c13","story_id":"CJ076508","role":"distractor","render":{"description":"Later zegt hij tegen iedereen dat je 's avonds nooit meer middenop de weg moet lopen.","half":"bottom","code":"SINSAG 0481"},"home":"1-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het bovenste stuk breekt midden in een zin af. Het onderste maakt hem af.","Het nummer is SINSAG 0481. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c10"},"on_success":{"fuse":["c1","c10"],"stack":["c1","c10"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.3058,"rank":0.6075,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ046312","role":"member","render":{"description":"Nooit 's nachts middenop de weg rennen: er kan een lijkstoet passeren.","place":"Surhuisterveen","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24424","original":"Wy woarden altyd warskôge: rin noait midden op 'e wei by joun of by nacht, hwant der kin us in lykstaesje passeare.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c2","story_id":"CJ102104","role":"member","render":{"description":"Sommigen moesten 's nachts het bed uit om lijkstoeten te zien. Je moest 's nachts nooit midden op de weg rennen.","place":"Augustinusga","prov":"Fr.","year":1973,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/37102","original":"Yn 'e Harkema en yn Stiensgea ha 'k wol guon kend dy't nachts fan bêd moesten om lykstaesjes to sjen.\nMen moest nachts noait midden op 'e wei rinne.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c3","story_id":"KOOIJMAN2266","role":"intruder","render":{"description":"Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","place":"Heesselt","prov":"Gld.","year":1963,"code":"SINSAG 0333","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/127631","original":"Dat weet ik ook nog. Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","lang":"Standaardnederlands","front":"original"},"home":"cab:4"},{"id":"c4","story_id":"CJ052415","role":"member","render":{"description":"De verteller vertelt over twee mannen die vaak lijkstoeten zagen. Je moet nooit middenop de weg lopen, omdat een onzichtbare lijkstoet je van de weg af kan drijven.","place":"Surhuisterveen","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25234","original":"Douwe Stavasius fan Grinzer Pein seach lykstaesjes.\nBoardzer Bruining fan Boelensloane ek. Dy leeft noch.\nMen mat noait midden op 'e wei rinne, hwant der kin us in lykstaesje oankomme, sûnder dat men it sjocht. Dan wurde jo fan 'e wei ôfsmiten.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Heesselt hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":4},"on_success":{"trail_note":0,"unlock_cabinet":4,"stack":["c1","c2","c4"]}},{"id":"1-3","type":"R1","difficulty":1.1165,"rank":0.2343,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"CJ011311","role":"omen","render":{"description":"Op een lege plek hoorde men 's avonds vanaf negen uur vaak getimmer. Jaren later is er een boerderij gekomen.","place":"Boornbergum","prov":"Fr.","year":1966,"code":"SINSAG 0487","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17750","original":"Yn 'e Surhústermieden by de feart wie in plak, dêr gong it nachts faek op in timmerjen. Njoggen ûre jouns dan bigong it. Altyd klunderen se dêr nachts om. Mar der wie dêrom neat as men der hinne gong.\n\"Hjir komt fêst in hûs\", seinen wy tsjin elkoar.\nIt hat noch jierren duorre, doe is dêr in nij spultsje delset woarn, flak by de brêge.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CJ096708","role":"omen","render":{"description":"Vader en moeder hadden een tweeling. Met negen maanden werd een van de kinderen ziek en stierf. Op het kerkhof zei de vader dat hun andere kind ook zou sterven. Hij had het in een kistje zien liggen. Toen ze thuiskwamen was het andere kind ook gestorven.","place":"Buitenpost","prov":"Fr.","year":1973,"code":"SINSAG 0483","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36140","original":"Heit en mem hienen twillingen. It iene berntsje woarde siik, doe wie 't njoggen maenden âld. It stoar en sy brochten it nei 't hôf ta. Doe sei heit: \"It oare berntsje hâlde wy ek net. Ik ha 't al yn 't kistje lizzen sjoen.\" Doe't se weromkommen fan 't tsjerkhôf wie 't oare berntsje ek dea.\nHeit en mem wennen doe yn 'e Twizeler Mieden.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c3","story_id":"WEV011104","role":"omen","render":{"description":"Hanen die 's avond om negen uur of later kraaien voorspellen regen en wind.","place":"Sellingen","prov":"Gr.","year":1965,"code":"TM 4001","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43504","original":"As de hoanen s oavends om n uur of negen of loater nog kraaien, den kriegn ie gauw regen en wind.","lang":"Gronings","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","9 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":9},"on_success":{"chime":9,"digit":{"value":9,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":2,"drawers":[{"id":"2-1","type":"P5","difficulty":0.6258,"rank":0.0,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"HOL000404","role":"variant","render":{"description":"Zien van witte juffer; met wit laken om spelen voor witte juffer.","place":"Ingen","prov":"Gld.","year":1962,"code":"SINSAG 0310","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/209537","original":"Witte vrouwen . Bij de pas (aanplant van wilgen of populieren met onderhout van elzen en essen) (lag dicht bij de woning van de zegslieden) zag men soms een witte gedaante lopen. Maar sommigen geloofden niet aan de witte juffer, zo werd Han Briene er van verdacht, dat hij soms de kinderen bang wilde maken door voor witte juffer te spelen (hij deed zich dan een laken om) Enige jongens wilden met Jas Gaosbeek, een niet volwaardige zoon van een bakker, een grap uithalen. Zij sloegen zich lakens om en gingen wandelen op een plaats, waar Jas passeren moest. Deze ging er echter niet voor door, maar begon de \"juffer\", die hij het eerst te pakken kreeg af te ranselen. De andere jongens sloegen toen op de vlucht","lang":"Standaardnederlands","front":"original"},"home":"2-1"},{"id":"c2","story_id":"HOL002208","role":"variant","render":{"description":"'s Avonds stok met krant aanzien voor witte juffer.","place":"Ochten","prov":"Gld.","year":1963,"code":"SINSAG 0310","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/210065","original":"Er moet een witte juffer gelopen hebben op het Zand (fruitteeltbedrijf) bij het witte hek (dit stond op de weg, die tussen twee kolken doorloopt. Keuken, hij was toen 18 jaar, ging eens met een kameraad naar Eldik (buurtschap) om een vriend te bezoeken. Deze bleek niet thuis. Op de dijk op de plaats waar beneden het witte hek stond, was een stok met krant er om gezet, als teken voor de castreur dat er \"keujes\" moesten gesneden worden. Janus stapte tegen deze stok aan, deze ging heen en weer, de kameraad beweerde, dat hij een witte juffer had gezien en was van dit idee, ook de volgende dag, niet af te brengen","lang":"Standaardnederlands","front":"original"},"home":"2-1"},{"id":"c3","story_id":"HOL002604","role":"variant","render":{"description":"Witte juffer die de weg vraagt, gooit hoed vol geld, en verdwijnt.","place":"Tiel","prov":"Gld.","year":1964,"code":"SINSAG 0310","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/210163","original":"Berend, den dakuil (een Van Uden) smeerde de daken van binnen aan met kalk, vandaar dat hij deze bijnaam kreeg. Eens liep Berend op de Grotebrugse grintweg bij de Twaalf Apostelen (straatje) toen een witte juffer hem de weg vroeg naar het veer. Berend zei haar die en nadat hij dit gedaan had, gooide zij hem de hoed vol met \"Berliner daolder\". Driemaal was Berend dit overkomen. Bij het veer gekomen wilde Berend haar bedanken, maar hij kreeg geen kans daartoe: zij was verdwenen.","lang":"Standaardnederlands","front":"original"},"home":"2-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Gelderland werd een voorwerp gezien: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.D.","summary":true},"home":"2-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1962.","Op die kaart staat een voorwerp. Welk?"],"lock":{"kind":"word","salt":"67d7e2afbf01cfe8","accepted_hashes":["1272dd76d14e3593d22f7cb3cd823cf1b98b3a3369139a3bbde8d84f3efa22be","207e43b02d129b0c0dfbeeb349d4db2e0bac182db44f6eec7eb49125c805ce67","70558341edfacfa7d12ead789fb04e1e71be69c1e3c5720908fff1bb2c5aff33","956df7f81b9e9ba44082df86f23b7c0c02c735328669f147d0ea247a5c2d1d14","d9d4c520b208f62bc5d211a9c0b2904c13726517fe231457e23ef4367af1a9d8"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"2-2","type":"P3","difficulty":1.2246,"rank":0.733,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ009417","role":"member","render":{"description":"Vroeger werden er 's nachts vaak witte wieven gezien in Westerein.","place":"De Westereen","prov":"Fr.","year":1966,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17488","original":"Froeger waerden der wol wite wiven sjoen nachts yn 'e Westerein.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c2","story_id":"KOOIJMAN1426","role":"intruder","render":{"description":"Vreemde mensen zouden zich verkleden als een weerwolf.","place":"Woudrichem","prov":"N.-Br.","year":1963,"code":null,"initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/125543","original":"In mijn jeugd ging het verhaal van de weerwolf, da 't toen zo was, da vreemde mense zich verkleed hadde. Dan sprake ze van de weerwolf.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"cab:3"},{"id":"c3","story_id":"CJ007910","role":"member","render":{"description":"Bij Hattum de Vries in het laantje spookte 's nachts altijd een wit wijf. De mensen durfden er 's nachts niet te komen, want ze werden er door dat witte wijf aan de kant gedreven naar het meertje toe. Zonder dat ze zelf iets deden, kwamen ze in het meertje terecht.","place":"Oudega","prov":"Fr.","year":1966,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17053","original":"By Hattum de Vries yn it loantsje spoeke nachts altyd in wyt wiif. De minsken doarsten dêr nachts noait to kommen. Hwant sy waerden dêr stadich troch dat wite wiif oan kant treaun nei de dobbe ta. Sûnder dat se it sels fornamen kommen se yn 'e dobbe torjochte.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c4","story_id":"DYKFRIES2187","role":"member","render":{"description":"In de tijd van keizer Lotharius woonden er veel witte wijven in Friesland. Dit waren kwaadaardige geesten en spoken die mensen en kinderen ontvoerden naar hun hol. Later werden deze wezens witte juffers genoemd, maar deze waren vriendelijk en behulpzaam van aard.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69790","original":"Ten tijde van keizer Lotharius werd men in Friesland veel geplaagd door geesten en spoken. Zij woonden op de spits van een kleinen heuvel in een kunstig hol, dat door geen menschenhanden was gemaakt. Gewoonlijk werden zij witte wijven genoemd. Aangaande hare uiterlijke gedaante wist men niet veel. Nachtelijke wandelaars, veehoeders, vrouwen en kinderen werden dikwijls door deze witte wijven weggevoerd naar hare holen en onderaardsche gangen. Daaruit hoorde men niet zelden zuchten, snikken en kindergeschrei. Zorgvuldig bewaakte men daarom zwangere vrouwen en kinderen, opdat dezen niet door de witte vrouwen zouden worden weggehaald. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een weerwolf.","De kaart over Woudrichem hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":3},"on_success":{"trail_note":2,"unlock_cabinet":3,"stack":["c1","c3","c4"]}},{"id":"2-3","type":"R2","difficulty":1.0511,"rank":0.5424,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"LAAN004a","role":"card","render":{"description":"Dr. Wumkes vertelt waar Widde Wieven gezien zijn. Zij zijn gezien bij Enum; te Krewerd en op de weg naar Arwerd. Zij hadden een voorkeur voor vreemde plaatsen. Op de grens van Slochteren en Schildwolde wandelden ze een eikenlaan op en neer in lange, witte gewaden. Zij zijn nooit overdag gezien, maar bang waren ze niet. Ze waren in griezelige steden en op kerkhoven. Ook waren ze altijd op plaatsen waar iets gebeurd was.","place":"Lellens","prov":"Gr.","year":1930,"code":"SINSAG 0310","initials":"E.F.","url":"https://www.verhalenbank.nl/items/show/42287","original":"Widde Juvvers\n\nWidde Wieven zijn overal; bij nacht en ontijd zweven zij langs lanen en wegen. Dr. Wumkes vertelt, dat zij gezien zijn op de börgstee van Alberda bij Enum; te Krewerd boeten 't loug op de weg naar Arwerd. Zij hadden voorkeur voor buitengewone plaatsen: een brug of vonder, een kruisweg, een wierde. Op de grens van Slochteren en Schildwolde wandelden ze een eikenlaan op en neer in lange, witte gewaden bij avond of nacht. Over dag heeft nooit iemand er een gezien. Bang zijn ze niet; ze duren wel op de griezelkste steden, alderdeegs op 't kerkhòf wel.\nOok zijn ze altijd op plaatsen, doar wat gebeurd is, zo op 't Huis de Wolf tussen Stad en Haren, en ook bij Den Andel.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c2","story_id":"CJ057303","role":"sill","render":{"description":"Meerdere mensen hebben door het bos twee witte wijven gezien.","place":"Opende","prov":"Gr.","year":1969,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25852","stain":"twee"},"home":"2-3"},{"id":"c3","story_id":"CJ020717","role":"card","render":{"description":"Een man heeft tijdens de bunzingjacht wel eens een witte juffrouw gezien.","place":"Harkema","prov":"Fr.","year":1966,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20675","original":"Wy ha wol us to murdzjen west. Doe ha wy in kear in wite juffer by de ikene beam sjoen.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c4","story_id":"ENGELB_15_003","role":"card","render":{"description":"Over bestaan van witte wieven en spit in deurpost.","place":"Geesteren","prov":"Ov.","year":1979,"code":"SINSAG 0161","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128566","original":"H.E.: Van de witn wiew he’j doar wa mangs van heurd?\nVr.Vr.: Van de witn wiew is ok niks van woar.\nH.E.: Nee, mer te geet ok um t verhaal, he. Joa he’j hier nog zonnen beuld, zonnen witn wievnbeuld. Ne, nee, nee (door elkaar heen gepraat, ze zijn het met elkaar niet eens)\nVr. [Wolberink, Jan]: Wat hadn ze bie ouns ok zegd, oh jee no valt mie t kenneke in zee Dat stun nog moal vuur joarn in de Twentse kraant. Als ik t met ene schoen had vastgebondn, gevondn als de ander gebondn.\nA.Ve.: ... t spit nog in n stiel van n nienduur nog zitn.\nF.Ve.: t Spit brengn.","lang":"Twents","front":"description"},"home":"2-3"},{"id":"c5","story_id":"CBOEK305","role":"card","render":{"description":"Een andere spookgeschiedenis vertelt over een witgesluierde dame die tussen twaalf en een uur door de muur heen komt. Als iemand haar rust verstoort, draait ze hem de nek om. Een sterke man gaat 's nachts naar het kasteel waar ze rondspookt en verdelgt haar voorgoed.","place":"Driebergen-Rijsenburg","prov":"Utr.","year":1892,"code":"SINSAG 0301","initials":"M.R.v.d.V.","url":"https://www.verhalenbank.nl/items/show/34810","original":"Een Spookgeschiedenis\nEen spookgeschiedenis zooals deze is er nog een, waarin eene geheimzinnige witgesluierde Dame het spook is; welke eveneens tusschen 12 en 1 uur komt, maar door den muur heen in de slaapkamer en roept, (wanneer zij iemand in de kamer ziet, welke het spook dooden wil), met een holle, nare grafstem: \"Wie stoort hier mijn rust?\" Daarop loopt zij toornig op den bevenden man toe en draait hem den hals om; daarna verdwijnt zij weer door den muur, alhoewel er geen deur in is. Nu durft niemand meer te wagen op het kasteel een nacht te slapen; totdat er eindelijk een moedige sterken man komt, op 't slot des nachts gaat en de witte Dame voor altijd verdelgt...\n(Breedvoerig ken ik deze historie niet meer.)","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c6","story_id":"EGGEN001705","role":"card","render":{"description":"Ontmoeten van door de lucht zwevende witte vrouw.","place":"Berg","prov":"L.","year":1970,"code":"SINSAG 0310","initials":"C.E.","url":"https://www.verhalenbank.nl/items/show/207880","original":"Onderwerp : wit wijf.\nTijd : einde 19de eeuw\nPlaats : Berg.\n\nIch weit noch, tot in daen tiēd mèr 'n paar hoezer in Berg sjtonge. En dao op Bemele aan, al gaar gein.\nOppenen aovend, heldere maon, gein mis of gèt, kaom 'n oud vruike nao hoēs, in Berg.\nMèh zie waor kaom aan 't begin van de grwoatstraot (grote straat), dao huërt zie geroēsj in de buim langs de weeg. Dao waor geine wind, en toch roēsjden 't. Zie kraog al gèt angs, en wol vlot wiejer loupe, pes aan de hoezer.\nMèh zie haet nog kaom eine sjtap gezat, dao kump 'n wit wiēf aangezwaef door de loch, zwoa grwoat wie 'ne wollek. \nZie ging rech-op van den angs.\nDoe die versjiening euver waor, leep dat auw minsjke wat 't loupe kòs, nao 't iërsjte hoēs.\nEn van dao haet me hör nao hoēs gebrach.","lang":"Limburgs","front":"description"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een O.","Opende. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c2","object":"window","text":"Opende"},"on_success":{"digit":{"value":2,"card":"c2","word":"twee","stained":"c2"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P1","difficulty":1.1309,"rank":0.9121,"note":"Alle vier noemen ze hetzelfde ding. Dat wordt het etiket. Niet ‘een beest’ schrijven.","cards":[{"id":"c1","story_id":"EDJSL003","role":"card","render":{"description":"Boerenknecht zegt tegen zijn meisje dat hij een boodschap moet doen, en dat zij als ze een kwade hond tegenkomt die zijn zakdoek moet geven. Ze komt inderdaad een hond tegen, gooit de zakdoek naar de hond en vlucht. Tijdens het eten ziet men dat hij stukken van een zakdoek tussen zijn tanden heeft zitten. Bij het doorzoeken van zijn kamer wordt de riem gevonden waarmee iemand in een weerwolf verandert. Zodra de riem in het vuur is gegooid staat de knecht die ver weg aan het werk was, bij de oven en probeert in het vuur te springen. Na het verbranden van de riem is de knecht verlost.","place":"Bladel","prov":"N.-Br.","year":1894,"code":"SINSAG 0823","initials":"E.d.J.","url":"https://www.verhalenbank.nl/items/show/9505","original":"De weerwolf\nEr was eens een boerenknecht die soms een weerwolf was.\nDe knecht vrijde met een van de meiden, maar zij wist van de prins geen kwaad. Op een keer waren ze een eind buiten het dorp gaan wandelen. Toen ze op huis aangingen, viel de schemer in.\nOpeens had de knecht zin weerwolf te worden.\nHij zei tegen de meid: \"Ik moet hier even een boodschap doen. Loop jij maar vast door, ik haal je wel in. Mocht je een kwade hond tegenkomen, die je wil bijten, gooi hem dan mijn zakdoek toe. Dan heeft hij iets om zijn tanden in te zetten, terwijl jij ervandoor gaat.\"\nHij ging weg, en een poosje later zag ze een grote hond op zich afkomen. Ze gooide hem de zakdoek toe en zette het op een lopen. Het dier scheurde de zakdoek aan flarden en at hem op. …","lang":"Standaardnederlands","front":"original"},"home":"3-1"},{"id":"c2","story_id":"BOEKV179","role":"card","render":{"description":"Een jongeman is een weerwolf. Wanneer hij wandelt met zijn meisje, voelt hij aankomen dat hij zal veranderen. Hij stuurt haar verder en waarschuwt haar voor een grote hond. Zij moet hem zijn zakdoek toewerpen, dan kan het meisje vluchten. Later zien zij en haar familie echter dat de stukken zakdoek tussen de tanden van de jongeman zitten. Weerwolven hebben altijd een band om hun middel. De boer, bij wie de jongeman in dienst is, verbrandt de band. De weerwolf probeert nog in het vuur te komen, maar hij wordt tegengehouden. Wanneer de band verbrand is, is de jongeman weer een gewoon mens.","place":"Bladel","prov":"N.-Br.","year":1896,"code":"SINSAG 0823","initials":"G.J.B.","url":"https://www.verhalenbank.nl/items/show/35060","original":"Van een Weerwolf.\n\nOp de Achterste hoef woonde indertijd een boer, en die boer had een knecht, en dat was een weerwolf. Op een eigenaardige manier zijn ze daar achter gekomen.\nDie knecht vrijde met een meid uit de buurt. Eens waren die twee samen buiten dorps (1) geweest en 't was al tusschen licht en donker toen ze op huis aan gingen. Ze waren al niet meer zoo heel ver van huis toen voelde hij een onweerstaanbare lust om weerwolf te worden; maar de meid merkte het natuurlijk niet. Hij zei tot haar: \"Ik moet hier eens effekens (2) van den weg af bij genen boer zijn; ga gij maar door: ik zal u wel inhalen. Maar komt ge soms een kwaden hond tegen, die op u aan bijt, gooit hem dan mijn zakdoek toe; dien zal hij misschien wel vatten. …","lang":"Standaardnederlands","front":"original"},"home":"3-1"},{"id":"c3","story_id":"SINBRABSAG185","role":"card","render":{"description":"Een jongeman is een weerwolf. Wanneer hij wandelt met zijn meisje, voelt hij aankomen dat hij zal veranderen. Hij stuurt haar verder en waarschuwt haar voor een grote hond. Zij moet hem zijn zakdoek toewerpen, dan kan het meisje vluchten. Later zien zij en haar familie echter dat de stukken zakdoek tussen de tanden van de jongeman zitten. Hierdoor weten ze dat hij een weerwolf is.","place":"Bladel","prov":"N.-Br.","year":1933,"code":"SINSAG 0823","initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/46940","original":"No. 185. Op de Achterste hoef bij Bladel woonde indertijd een boer, en die boer had een knecht, en dat was een weerwolf. Op 'n vreemde manier zijn ze dat aan de weet gekomen. Die knecht vrijde met een meid uit de buurt. Eens waren die twee samen buitendorps geweest en 't was al tusschen licht en donker, toen ze op huis aan gingen. Ze waren al niet ver meer van huis toen hij een onweerstaanbaren lust voelde om weerwolf te worden; maar de meid merkte dat natuurlijk niet. Hij zei tot haar: \"Ik moet hier eens effekens van den weg af bij genen boer zijn, ga gij maar door: ik zal oe wel inhalen. Maar komt ge soms een kwaden hond tegen, die naar oe bijt, gooit hem dan mijn zakdoek toe; dien zal hij wel vatten. …","lang":"Standaardnederlands","front":"original"},"home":"3-1"},{"id":"c4","story_id":"LYST009","role":"card","render":{"description":"Een paartje loopt 's avonds te wandelen. De jongen moet zijn behoefte doen, maar voordat hij de bosjes in verdwijnt adviseert hij het meisje om, als een beest haar zou overvallen, het haar zakdoek voor de muil te werpen. Er komt inderdaad een gevaarlijk beest op het meisje af. Ze gooit haar zakdoek voor zijn bek en het beest verscheurt hem. Als de jongen weer terugkomt ziet het meisje dat hij resten van haar zakdoek tussen zijn tanden heeft zitten. Ze weet nu dat hij een weerwolf is en zegt dat ook tegen hem. De jongen verdwijnt en is nooit meer terug gekomen.","place":"Erp","prov":"N.-Br.","year":1953,"code":"SINSAG 0823","initials":"F.W.J.S.","url":"https://www.verhalenbank.nl/items/show/13223","original":"De Weerwolf\nEen vrijer bracht 's avonds z'n meisje naar huis. Onderweg zei ie: \"Ik moet even mijn behoefte doen. Als je in tussentijd een dier of zoiets op je af ziet komen, gooi het dan je zakdoek voor z'n kop.\" Toen de jongen weg was, kwam er een dier op het meisje aangelopen. Ze slingerde haar zakdoek voor z'n muil en het beest verscheurde hem. Even later kwam de jongen terug en hij vroeg zijn meisje of er iets gebeurd was. Ze vertelde wat er was voorgevalllen en terwijl keek ze hem strak aan. Toen zei ze hem: \"Ik geloof, dat jij het beest bent geweest, want je hebt de stukken zakdoek nog tussen je tanden zitten\" Onmiddellijk was de vrijer verdwenen, en het meisje heeft hem nooit teruggezien.","lang":"Standaardnederlands","front":"original"},"home":"3-1"}],"hints":["Lees de vier nog eens. Let op wat er in elk van de vier vóórkomt, niet op wat erin gebeurt.","Het is een voorwerp.","Begint met een Z. 7 letters."],"lock":{"kind":"word","salt":"67d7e2afbf01cfe8","accepted_hashes":["60831a4a278d1d9ad2eda799bab827948226a081dd82ecf6f45c01ea81936455","7f5940117b226aea32e6e91b516526c1f39c7b62982c2adb459ade98670cb4b0"]},"on_success":{"print_label":true,"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c4"}},{"id":"3-2","type":"P3","difficulty":1.3078,"rank":0.9137,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ084112","role":"member","render":{"description":"Één van zeven meisjes is een nachtmerrie en één van zeven jongens een weerwolf.","place":"Rottevalle","prov":"Fr.","year":1971,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32830","original":"Se sizze fan 'e sawn famkes út ien húshâlding is ien in nachtmerje en fan 'e sawn jonges út in húshâlding is ien in wearwolf","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c2","story_id":"CJ101519","role":"member","render":{"description":"Een van zeven dochters is een nachtmerrie; een van zeven zonen is een weerwolf.","place":"Drachtstercompagnie","prov":"Fr.","year":1973,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/36981","original":"Ien fan sawn famkes út ien gesin wie in nachtmerje.\nIen fan sawn jonges út ien gesin wie in wjerwolf.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c3","story_id":"CJ085401","role":"member","render":{"description":"Een van zeven broers is een weerwolf. Als hij weer een kuur heeft, moet men hem een oud schort of iets toewerpen. Dat verscheurt hij dan. Als men iemand met de draden uit zijn mond ziet, kan men ervan opaan dat dat een weerwolf is.","place":"Rottevalle","prov":"Fr.","year":1971,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/33002","original":"In wearwolf is in minske, dy forropt de boel. 't Is ien fan sawn jonges (7 bruorren). As er wer sa'n kuer krijt, dat er hwat forskuorre mat, mat men him in âld skelk of sahwathinne tasmite. Us mem sei, dan gebeurde 't wol dat him even letter de triedden ta de mûle úthongen.\nAs men sa'n ien seach, dy't triedden ta de mûle út hie, koe men der fan op oan dat it in wearwolf wie. Dêr koe men se oan herkenne.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"HOL001916","role":"intruder","render":{"description":"Bekend met mensen die kunnen weerwolven; vrouw ziet weerwolf of duivel.","place":"Maurik","prov":"Gld.","year":1963,"code":null,"initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/209980","original":"Men wist nog wel mensen te noemen, die de naam hadden te kunnen weerwolven. Wat ze deden, wist men niet.\nDe \"aauwe\" Roel moest de weerwolf of was het \"den duvel\" verdrijven. Zij zag hem komen en schreeuwde 's nachts: \"Daor heddum al weer\" (moet in Ingen gebeurd zijn, de \"aauwe\" Roel was de buurvrouw.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"cab:5"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Maurik hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c4","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c1","c2","c3"]}},{"id":"3-3","type":"R3","difficulty":1.111,"rank":0.8462,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"CJ071510","role":"door","render":{"description":"Een weerwolf is een jongeman die op een paard rijdt. Hij plaagt het paard net zoals een nachtmerrie een mens plaagt. Het is een van zeven broers.","place":"Rohel","prov":"Fr.","year":1969,"code":"TM 3107","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28067","original":"In wjerwolf is in manspersoan, - meastal in jongkeardel -, dy't op in hynder rydt. Hy pleaget dat hynder, krekt as in nachtmerje de minsken. 't Is ien fan sawn bruorren. Ik ha wol ien kend, dy wenne yn Warffum.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c2","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c3","story_id":"VVUNL049","role":"card","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":"SINSAG 0824","initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c4","story_id":"LYST008","role":"card","render":{"description":"Een boerenknecht haalt iedere nacht precies om twaalf uur een hoepeltje uit de lindeboom. Hij hangt de hoepel om zijn nek en verandert in een weerwolf. Hij loopt een tijdje rond en verscheurt alles wat er in zijn buurt komt. Hierna wordt hij weer gewoon mens. De boer vindt zijn gedrag maar vreemd en vraagt raad aan de pastoor. De pastoor heeft door dat de boerenknecht een weerwolf is, en adviseert de boer om de knecht een boodschap te laten doen waarbij hij nooit om middernacht weer thuis kan zijn. Op de afgesproken nacht haalt de pastoor om middernacht de hoepel uit de boom. De knecht staat onder die boom en ziet alles. Hij vlucht en komt nooit meer terug.","place":"Erp","prov":"N.-Br.","year":1953,"code":"SINSAG 0803","initials":"F.W.J.S.","url":"https://www.verhalenbank.nl/items/show/13222","original":"De Weerwolf\nEen boerenknecht kroop 's nachts klokslag 12 uur in de lindenboom voor de boerderij. Boven in de boom hing voor gewone mensen onzichtbaar een hoepeltje. Dat hing de knecht om zijn hals. Als ie uit de boom geklauterd was, liep ie in de gedaante van een hond weg en verscheurde alles wat hem in de weg kwam. Als ie een tijd zo rondgelopen had, was ie weer gewoon mens. Na een tijd was het de boer, bij wie de weerwolf in dienst was, opgevallen, dat zijn knecht nacht op nacht weg was. Hij ging naar de pastoor en die had het zaakje meteen door. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c5","story_id":"TINNEV042","role":"card","render":{"description":"Twee mannen zoeken grasstengels om te snijden. Als ze er geen vinden gaan ze maar naar huis. Wanneer ze uit elkaar zijn gegaan ziet de ene man ineens een grote wolf op zijn pad. De volgende morgen vraagt de andere man aan hem of hij de wolf heeft gezien.","place":"Didam","prov":"Gld.","year":1944,"code":"SINSAG 0823","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22388","original":"29.\nPeter ging op een kier met Dorus mieskes sni'je. Mao zi'j konne de gin vinne en wolle daorum weer op huus aan. De weg liep deur een buske. Dorus vroeg aan Peter offe um nao huus sol brenge. \"Loop nao da galg\", antwore Peter en kroap onder de scheibeum nève de weg hèèr.\n\"Hi'j is ter\", riep Dorus um nao. Ienéns stong d'r een grote wolf op de bosweg. Hi'j wol niet op zied gaon. Daorum drèèje Peter de met een flinken boag umhen. Toe e is umkek zag e niks meer. Umdat Peter geld neudig had ginge de 's marges weer op uut um smele te zuke. Ien Kilder was Dorus al met een groten trop aan 't sni'je. Toe hi'j Peter zag riep tem toe: \"Wasse d'r now, of niet?\".","lang":"Liemers","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c1","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c2"},"stack":["c2","c3","c4","c5"]}}]},{"id":4,"label":"Spoken","digit":3,"drawers":[{"id":"4-1","type":"P2","difficulty":3.1343,"rank":0.2092,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"KOOIJMAN2326","role":"target","render":{"description":"Vroeger zagen ze wel eens een wagen met twee paarden door de lucht rijden. Bij onweer werd dat ook gezegd.","place":null,"prov":"Gld.","year":1963,"code":"SINSAG 0478","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/127722"},"home":"4-1"},{"id":"c2","story_id":"KOOIJMAN1559","role":"helper","render":{"description":"Mensen zagen 's nachts een ruiter op een paard door de lucht vliegen.","place":"Culemborg","prov":"Gld.","year":1963,"code":"SINSAG 0478","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/125747","original":"Dat ze 's nachts een ruiter te paard door de lucht hadden zien vliegen.","lang":"Standaardnederlands","front":"original"},"home":"4-1","geo":[51.955,5.22778]},{"id":"c3","story_id":"HOL002513","role":"helper","render":{"description":"Spokerij op boerderijen, 's avonds lopen dors- en wanmolen.","place":"Kapel-Avezaath","prov":"Gld.","year":1964,"code":"SINSAG 0478","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/210140","original":"Op de boerderij bij de dames Versteeg spookte het. (Dit was op Aldenhaaf, zie opname Koehein). Op Teisterbant was het vroeger soms helemaal mis. Er woonde daar toen een Versteeg. 's Avonds hoorde men de dorsmolen lopen, ook de wanmolen en de hakselmachine (Men sprak van \"kortsnijmachine\", ook bij mij thuis). Den knecht zei tegen Versteeg: \"Laote we der een paor gaarven deur gooie, want de mesine lop toch\" \nHierop wilde Versteeg toch niet ingaan (zie opname Van Zijtveld)","lang":"Standaardnederlands","front":"original"},"home":"4-1","geo":[51.88,5.37639]},{"id":"c4","story_id":"HOL002610","role":"helper","render":{"description":"Spoken blijke ontsnapte kalveren te zijn.","place":"Tiel","prov":"Gld.","year":1964,"code":"SINSAG 0478","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/210169","original":"Een neef van grootvader Boudewijn bracht eens, het was met Tielse kermis, een meisje naar huis. In Wadenoijen bij de Pijpekasten werd het meisje bang (die Pijpekasten was een rij huisjes heb ik begrepen). Ook een paar andere kermisgangers durfden niet verder te lopen, want zij zagen daar dingen springen. (Het was een donkere avond). Neef Boudewijn ging er moedig op af. En wat was het geval. Er liepen twee kalveren op de weg. Die waren uit hun wei gegaan.","lang":"Standaardnederlands","front":"original"},"home":"4-1","geo":[51.88667,5.42917]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Culemborg.","Zoek Deil op de kaart."],"lock":{"kind":"place","target_geo":[51.88417,5.24306],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Deil"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c4"}},{"id":"4-2","type":"P3","difficulty":1.212,"rank":0.7143,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ015603","role":"intruder","render":{"description":"Een visser ziet een juffer in witte kleren en besluit haar te volgen. Het witte wief verdwijnt echter even snel als ze verschenen is.","place":"Broeksterwâld","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19893","original":"Douwe syn broer Anne Feddema hie to fiskjen west. Hy hie nei 't tichtset ta west en farde de Lyts út wei werom de kant nei de brêge út. Doe kom der in juffer oan yn sniewite klean. Hy tocht: Ik wol wite hwer't dy keart, dat hy hie 't eech net fan har ôf. Doe't er oan har ta wie, died er de fêstsetter yn 'e kant en krekt doe't er dat die, wie de wite juffer fuort.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:2"},{"id":"c2","story_id":"DYKFRIES2153","role":"member","render":{"description":"Op de Leppedijk spookte een gloeiend veulen rond. Een boerenmeid was tot laat in het dorp gebleven en moest alleen naar huis. Toen ze gewaarschuwd werd voor het spookveulen, beweerde ze dat ze het dier haar kousenband in de bek zou doen en op het beest naar huis zou rijden. Toen ze het dier echter daadwerkelijke ontmoette, schrok ze hevig en rende ze naar huis.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69329","original":"Op den Leppedijk, niet ver van Oldeboorn, spookte voorheen een gloeiend veulen. Eene boerenmeid was op zekeren avond wat laat in het dorp gebleven en toen haar gezegd werd, dat het veulen haar wel kon ontmoeten, zei ze, dat zij hem dan haar kouseband in den bek zou doen en op hem naar huis rijden. Maar toen zij, op den weg gekomen, het veulen eensklaps vóór zich zag met den bek wijd opengesperd, toen liep zij zoo hard zij kon om tehuis te komen.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"DYKFRIES2191","role":"member","render":{"description":"Liep iemand daar bij nacht, dan kon hij onverwachts een wit veulen in vliegende vaart zich voorbij zien snellen, waarna het plotseling verdween.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69795","uncatalogued":true},"home":"4-2"},{"id":"c4","story_id":"DYKFRIES2156","role":"member","render":{"description":"Een boer uit Westdongeradeel had regelmatig ontmoetingen met een plaaggeest. Het dier liep steeds met hem mee naar huis, maar deed hem verder niets. De boer zorgde ervoor dat hij het dier altijd een stukje roggebrood kon aanbieden. Zijn dienstmeid beweerde dat zij dapperder zou zijn en dat ze als zij het dier tegenkwam, er wel op naar huis zou rijden. Toen zij het dier eens tegenkwam, zette het zijn voorpoten op haar schouders, waardoor de meid gedwongen was het gewicht van het dier mee te dragen op haar weg naar huis.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69345","original":"In Westdongeradeel woonde weleer een boer die veel last had van een plaagbeest. Was de man 's avonds bij duister op weg naar zijn huis, dan kwam hem meest altijd zulk een spookdier op zijde. Het vergezelde hem tot aan zijn erf. Eens zelfs was het meegegaan over het bruggetje, dat aan den weg over de gracht lag. Maar dat was dan ook alles; eigenlijk kwaad deed het hem niet. Hij zorgde altijd een stuk roggebrood bij zich te hebben, waarop hij 't beest dan onthaalde. Dit scheen daar smaak in te vinden, nam het gretig aan en liet den boer ongedeerd. Maar de man was toch altijd ontsteld als hij in huis kwam. Zijne dienstmeid vond dit wel wat dwaas en schroomde ook niet voor hare meening uit te komen. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Broeksterwâld hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":2},"on_success":{"trail_note":1,"unlock_cabinet":2,"stack":["c2","c3","c4"]}},{"id":"4-3","type":"R4","difficulty":1.1317,"rank":0.4167,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"KEMP322","role":"top","render":{"description":"Een vrouw komt op een veld altijd een verschijning tegen. Op aanraden van een geestelijke vraagt ze hem op een keer wat hij wenst.","place":"Broek","prov":"L.","year":1925,"code":"SINSAG 0402","initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/43449","half":"top"},"home":"4-3"},{"id":"c2","story_id":"CJ112316","role":"half","render":{"description":"Als iemand de kist omhoog probeert te halen, zakt die steeds dieper de grond in. Vroeger is er op die plaats een meneer vermoord. Hij zou nog altijd rondspoken.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c3","story_id":"CJ053307","role":"half","render":{"description":"Als zijn erfgenamen verzuimen hem op die plek te begraven, blijft de geest van de boer ronddolen. Als de boer alsnog bij het paaltje begraven wordt, is het met het spoken gedaan.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c4","story_id":"KEMP325","role":"half","render":{"description":"Nu krijgt hij, als hij 's avonds terug komt van de herberg, slagen in zijn gezicht van een vreemde gedaante. Van een geestelijke moet hij een heilige Mis lezen en opletten wat er bij de consecratie gebeurt. En de jongen ziet dan zijn moeder! Hij herinnert zich zijn verzuim meer en maakt het goed. Sindsdien heeft hij geen last meer gehad van de verschijning.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c5","story_id":"CJ069906","role":"half","render":{"description":"'s Nachts hoorden ze er altijd geluiden, de vermoorde mensen spookten er dan rond. Op het laatst werden de bewoners zo bang, dat ze verhuisd zijn.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"},{"id":"c6","story_id":"KEMP322","role":"bottom","render":{"description":"De geest is tijdens zijn leven een bedevaart vergeten en als de vrouw deze alsnog voor hem doet, zal hij verlost zijn. De vrouw doet het en de geest bidt daarna zo krachtig voor haar ziel dat zij al na drie maanden overleed.","half":"bottom","code":"SINSAG 0402","stain":"drie"},"home":"4-3"},{"id":"c7","story_id":"BLECOURTNB0007","role":"half","render":{"description":"plaatsen aangeeft, is dat hij na zijn dood meteen gloeiend hoofd moet ronddwalen op de plaats waar hij de eed durfde te zweren.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘vrouw’ opnieuw.","Het nummer is SINSAG 0402. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c6","object":"typewriter"},"on_success":{"fuse":["c1","c6"],"type_line":"Verteller: de vorige assistent.","digit":{"value":3,"card":"c1","word":"drie","stained":"c6"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
